def update_records(filename):
    if not filename or os.path.basename(filename) != filename: raise ValueError("invalid filename")
    if not filename.endswith((".yaml", ".yml")): raise ValueError("unsupported file type")
    full_path = os.path.join(CONFIG_DIR, filename)
    with open(full_path) as f: cfg = yaml.safe_load(f)
    return cfg

